	title 'QD Pixel Maps        GS ROM 2.0'*****************************************************************			   **	      Pixel Maps		   **	     Version 2.0		   **	   December 23, 1986	   **			   **			   ** 2/10/89	Mensch		   ** * Modified the toslices routine to be able to go fast when we* are using shadowed memory as well.** 4/6/89	Mensch* Modified to clear the proper dirty flags.*****************************************************************	MACRO	DirtyPort	ldx #512	; switch to qdDPage2	lda <DirtyDPFlags,x	; get the proper flags	and #PortBad	; turn off both patterns	sta <DirtyDPFlags,x	MEND	*****************************************************************			   **	Copyright (C) 1985-1987	   **	All Rights Reserved		   **	Apple Computer, Inc.	   **			   *****************************************************************	blanks off	string asis		include 'all.macros'			MACRO&lab	MoveRect &Src,&Dest&lab	lda &Src	sta &Dest	lda &Src+2	sta &Dest+2	lda &Src+4	sta &Dest+4	lda &Src+6	sta &Dest+6	MEND				include ':QDEquates:qd.data.asm'	INCLUDE ':QDEquates:core.globals1'	INCLUDE ':QDEquates:core.globals2'	INCLUDE ':QDEquates:region.equs'	INCLUDE ':QDEquates:slice.equs';-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT BFBICSlice	IMPORT BFCopySlice	IMPORT BFORSlice	IMPORT BFXORSlice	IMPORT BusyEC	IMPORT BusyErr	IMPORT CheckPenVis	IMPORT DeRefA	IMPORT DeRefB	IMPORT DeRefC	IMPORT FBICSlice	IMPORT FCopySlice	IMPORT FORSlice	IMPORT FXORSlice	IMPORT InitUp3Rgns	IMPORT QDStart	IMPORT TestGPs	IMPORT WideOpen	IMPORT bRealFastCopy	IMPORT fBFBICSlice	IMPORT fBFCopySlice	IMPORT fBFORSlice	IMPORT fBFXORSlice	IMPORT fFBICSlice	IMPORT fFCopySlice	IMPORT fFORSlice	IMPORT fFXORSlice	IMPORT fRealFastCopy;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY BackSliceAdrTable	ENTRY CallPP	ENTRY FastBackSliceAdrTable	ENTRY FastSliceAdrTable	ENTRY IsDestPort	ENTRY RealFastBack	ENTRY RealFastForward	ENTRY SandDEqual	ENTRY SliceAdrTable;                copy pixel.maps/stdpixels****************************************************************** StdPixels** Standard pixel painting routine.  Inputs are already on* zero page as follows when this gets control.**        SrcLocInfo*        DestLocInfo (this lives in same memory as PortLocInfo)*        SrcRect*        DestRect*        XFerMode*        RgnHandleA*        RgnHandleB*        RgnHandleC	(MaskRgn)** Change History** June ?, 1986	This routine did not handle source and*	destination pixel maps crossing bank boundries*	until now.* August 8, 1986	When the src and dest pixel maps were not equal*	chunkiness, the bank reg was left on stack and*	system crashed.** November 18, 1986	It now handles stretching. oh my.** March 11, 1987	If pen is not visible, I don't return error*	in a-reg any more.*****************************************************************	EXPORT iStdPixelsiStdPixels	PROC*              using CoreDATA*              using E0Vectors*              using PicInfo*              using ErrorDATA;-------------------------------------------------;; If the dest loc is the same as the current; graf port, then we check if a picture	is being; captured.;	jsr IsDestPort	bcc SkipPicture	lda #MapNoun	jsl PutPictStuff	bcc NoPicErr	rtlNoPicErr		; SkipPicture	jsr CheckPenVis	; does not come back if not vis	jml RgnBlt	ENDP;                copy pixel.maps/rgnblt****************************************************************** RgnBlt** This was the original StdPixel (back before stretching was* invented [or rediscovered]).** Modification History:* 12/1/87      GCP	   Moved calls to setup routines. They're now*	   made after we decide which direction	we are*	   going. When we want to seek up through the*	   region we now call InitUp3Rgns.****************************************************************	EXPORT iRgnBltiRgnBlt	PROC*              using CoreDATA*              using E0Vectors*              using PicInfo*              using ErrorDATA	phb;-----------------------------------------------;; Are we transfering to and from pixel maps of; the same chunkiness?;	lda SrcSCB	eor DestSCB	and #%0000000010000000	beq SameChunk	lda #NotEqualChunkiness	jmp ReportError;-----------------------------------------------;; Now we run through lots of code to set up all; variables required by the slice routines.;SameChunk		; ;----------------------------------------------;; First, we clip the Source Rect to the	Source; Bounds Rect.  If it is not inside, we	are; done.  At the same time, we adjust the destination; point by any amount that we clip the upper left; of the source rect.;	lda SrcBounds	cmp SrcRect	bmi TopOK1	sec	; first i calculate	SrcBoundsTop - SrcTop	sbc SrcRect	; we know this is a	num < 0	clc	; I then add it to DestPoint	adc DestPoint	sta DestPoint	lda SrcBounds	sta SrcRectTopOk1	lda SrcBounds+2	cmp SrcRect+2	bmi LeftOK1	sec	; now i calculate SrcBoundsLeft-SrcLeft	sbc SrcRect+2	; we know this is a	num < 0	clc	; I then add it to DestPoint	adc DestPoint+2	sta DestPoint+2	lda SrcBounds+2	sta SrcRect+2LeftOK1	lda SrcBounds+4	cmp SrcRect+4	bpl BottomOK1	sta SrcRect+4BottomOK1	lda SrcBounds+6	cmp SrcRect+6	bpl RightOK1	sta SrcRect+6RightOK1	lda SrcRect	cmp SrcRect+4	bmi VValid1	jmp NeverMind	; rect not valid, Top > BottomVValid1	lda SrcRect+2	cmp SrcRect+6	bmi HValid1	jmp NeverMind	; Rect not valid, Left > RightHValid1		; ;-------------------------------------------;; Now we stretch the dest point into a; rectangle of the same size as the clipped; source rectangle.;	ldx #2DestRectLoop	lda SrcRect+4,x	; calculate size	sec	sbc SrcRect,x	clc	; add to point	adc DestPoint,x	sta DestPoint+4,x	dex	dex	bpl DestRectLoop	jsl SharedMRSetup	; calls make minrect	bcc SomethingLeft	jmp AllDoneSomethingLeft		; ;-----------------------------------------------;; Now I check to see if the dest rect got ; clipped.  If it did get clipped, then	I must; adjust the source	rect accordingly.	ldx #6AdjSrcLoop		; 	lda MinRect,x	; I subtract DestRect from MinRect	sec	; If not clipped on	that side result	sbc DestRect,x	; is zero.  If clipped at top or left,	beq SideStillOK	; then result is positive and so is	clc	; amount src must be adjusted.  If	adc SrcRect,x	; clipped at bot or	right, then result	sta SrcRect,x	; is negative and so is amount src SideStillOK	dex	; must be adjusted.	dex	bpl AdjSrcLoop*		; move clipped value of destrect*		; back to DestRect	MoveRect MinRect,DestRect	jsl ShareShieldStuffNotSame	jsl ShieldCursor	; use minrect to shield cursor*		; move orig clip rect back to dest*		; so that rgn clipping can work!	MoveRect DestRect,MinRect;-------------------------------------------------;; Source and dest Rects are entirely contained; in the bounds rects.;; Figure out if we are painting in and out of; the same pixel map.;	ldx #0	; use x and y as flags for	txy	; backwards and forwards	jsr SandDEqual	bcc DifferentMaps;-------------------------------------------------;; The maps are the same.;	lda DestPoint	; convert dest y to	global coord's	sec	; and push it on the stack	sbc DestBounds	pha	lda SrcRect	; convert src y to global coord's	sec	; and compare it to	value on stack	sbc SrcBounds	cmp 1,s	bcs VertIsForward	dey	bra HorIsForward	; if vert is backwards then hor canVertIsForward	lda DestPoint+2	; Convert DestX to global and replace	sec	; global y value on	stack	sbc DestBounds+2	sta 1,s	lda SrcRect+2	; convert SrcX to global and compare	sec	; to value on stack	sbc DestBounds+2	cmp 1,s	bcs HorIsForward	dexHorIsForward	pla	; clear the stackDifferentMaps	sty VertBackward	stx HorBackward;-------------------------------------------------;; Set up the SrcRef	and DestRef pointers.;	pea 0	; put room for result on stack	pea 0	cpy #0	; if y is still pos	then we go	bpl UseSrcTop	; from top to bottom	lda SrcRect+4	; get bottom minus one in a reg	dec a	bra PushStart1UseSrcTop	lda SrcRect	; get top in a-regPushStart1	sec	; convert to global	coord's	sbc SrcBounds	pha	; push it	pei SrcWidth	_Multiply	pla	plx	clc	adc SrcPixelMapRef	sta SrcRef	txa	adc SrcPixelMapRef+2	sta SrcRef+2	pea 0	; put room for result on stack	pea 0	bit VertBackward	bpl UseDestTop	lda DestRect+4	dec a	bra PushStart2UseDestTop	lda DestRectPushStart2	sec	sbc DestBounds	pha	pei DestWidth	_Multiply	pla	plx	clc	adc DestPixelMapRef	sta DestRef	txa	adc DestPixelMapRef+2	sta DestRef+2;-------------------------------------------------;; Set up looping vars, clipping and the	address; of the slice routine to be used.;	pei DestRef+1	; set the data bank	register to	plb	; bank containing dest map	plb	clv	lda XFerMode	bpl NotInverted	sep #%01000000	; set the overflowNotInverted	php	; save this on stack	lda DestRect+4	; assume we go backwards	dec a	sta CurrentY	bit VertBackward	bmi BackLp	lda DestRect	; bad guess, we go forewards	sta CurrentY	jsl SliceSetup	jsl SetUpScanPtrs	jsl Init3Regions	jsl SetSliceAdrPaintLoop		; 	jsl Seek3Regions	plp	; get v flag back	php	; save for later too	jsl ToSlice	lda CurrentY	inc a	cmp DestRect+4	bpl TheEnd	; unsigned compare dummy 28 Mar 86	sta CurrentY	lda SrcWidth	clc	adc SrcRef	sta SrcRef	bcc NoCarrySrc	; must carry accross banks	inc SrcRef+2NoCarrySrc	lda DestWidth	clc	adc DestRef	sta DestRef	bcc NoCarryDest	inc DestRef+2	phb	; must also update the data bank	lda DestRef+1	; register	sta 0,s	plbNoCarryDest		; 	bra PaintLoopBackLp		; 	jsl SliceSetup	jsl SetUpScanPtrs	jsl InitUp3Rgns	jsl SetSliceAdrBackLoop		; 	jsl Seek3Regions	; this will be very	slow *		; because seekrgn is optimized *		; for forward.	plp	; get v flag back	php	; save for later too	jsl ToSliceBackHere2		; 	lda CurrentY	dec a	cmp DestRect	bmi TheEnd	sta CurrentY	lda SrcRef	sec	sbc SrcWidth	sta SrcRef	bcs NoBorrowSrc	; must borrow from high word	dec SrcRef+2	; if crosses bankNoBorrowSrc	lda DestRef	sec	sbc DestWidth	sta DestRef	bcs NoBorrowDest	dec DestRef+2	phb	; must also update the data bank	lda DestRef+1	; register	sta 0,s	plbNoBorrowDest		; 	bra BackLoopTheEnd	jsl UnShieldCursor	plp	; clean up stackAllDone	jsl Free3RegionsNeverMind	plb	lda #0	clc	rtlReportError	plb	; added restore b here SEG 8 Aug 86	sec	rtl;----------------------------------------------------;; Local routine to determine if the source and dest; are equal.;	EXPORT SandDEqualSandDEqual		;       	lda SrcPixelMapRef	; are we painting in and	cmp DestPixelMapRef	; out of same pixel	map?	bne DM	lda SrcPixelMapRef+1	cmp DestPixelMapRef+1	bne DM	sec	rtsDM	clc	rts	ENDP****************************************************************** SharedMRSetup** This is code shared by rgnblt and stetch to setup the* minrect and to clip the destrect to the bounds rect of* rgn C.** At the very end this routine calls makeMinRect and then* returns with the same condition codes	set.*****************************************************************	EXPORT iSharedMRSetupiSharedMRSetup	PROC*              using E0Vectors*              using CoreData;-------------------------------------------;; Now we have to clip the dest rect to the; dest bounds rect and the clipping region; bounding box.;	jsr DeRefA	jsr DeRefB	jsr DeRefC	; we do C too now and then	ldy #2	lda [RgnPtrC],y	; we intersect DestRect and Bounds	cmp DestRect	; of rgn c	bpl RgnTopBigger	lda DestRectRgnTopBigger	sta MinRect	iny	iny	lda [RgnPtrC],y	cmp DestRect+2	bpl RgnLeftBigger	lda DestRect+2RgnLeftBigger	sta MinRect+2	iny	iny	lda [RgnPtrC],y	cmp DestRect+4	bmi RgnBotSmaller	lda DestRect+4RgnBotSmaller	sta MinRect+4	iny	iny	lda [RgnPtrC],y	cmp DestRect+6	bmi RgnRightSmaller	lda DestRect+6RgnRightSmaller	sta MinRect+6;----------------------------------------------------------;; Now the intersection of the dest rect	and the bounds of; rgn c are in MinRect.;	bit ClipToPortToo	bpl SkipPortRect	jsr IsDestPort	bcc SkipPortRect	ldy #o_PortRect	lda [PortRef],y	cmp MinRect	bmi MinTopOK	sta MinRectMinTopOK	iny	iny	lda [PortRef],y	cmp MinRect+2	bmi MinLeftOK	sta MinRect+2MinLeftOK	iny	iny	lda [PortRef],y	cmp MinRect+4	bpl MinBotOK	sta MinRect+4MinBotOK	iny	iny	lda [PortRef],y	cmp MinRect+6	bpl MinRightOK	sta MinRect+6MinRightOK		; SkipPortRect		; 	jsl MakeMinRect	rtl	ENDP****************************************************************** ShareShieldStuff** If the source and	dest pixel maps are	the same,* then the minrect	needs be enlarged to the union* of the src and dest rects.** Warning!!!** This is not enough.  If the source is	the screen and* the dest is not, we still want to shield the cursor* accordingly.  I don't know how to handle this yet.*****************************************************************	EXPORT iShareShieldStuffiShareShieldStuff	PROC	jsr SandDEqual	bcc NotSame	lda DestRect	cmp SrcRect	bmi UseDest1	lda SrcRectUseDest1	sta MinRect	lda DestRect+2	cmp SrcRect+2	bmi UseDest2	lda srcRect+2UseDest2	sta MinRect+2	lda DestRect+4	cmp SrcRect+4	bpl UseDest3	lda SrcRect+4UseDest3	sta MinRect+4	lda DestRect+6	cmp SrcRect+6	bpl UseDest4	lda SrcRect+6UseDest4	sta MinRect+6NotSame	rtl	ENDP;                copy pixel.maps/pp.to.port****************************************************************** Revision History** 6 Oct 1986   SEG	   Changed all the entry points so that*	   they call QDStart.  This does the right*	   thing with the direct page and incs*	   the busy flag.  Original code did not*	   inc the busy flag.*********************************************************************************************************************************** PPToPort**     PtrToSourceLocInfo	; 4*     PtrToSourceRect	; 8*     DestX		; 10*     DestY		; 12*     Mode		; 14*** The LocInfo Record Looks Like**     MasterSCB	    byte*     Reserved	    byte*     PtrToPixelMap	    long*     Width	    word*     BoundsRect	    rect*****************************************************************	EXPORT PPToPortPPToPort	PROC*              using CoreData*              using E0VectorsOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PPMode	equ RTL2+3PPDestY	equ PPMode+2PPDestX	equ PPDestY+2PPSrcRect	equ PPDestX+2PPLocInfo	equ PPSrcRect+4;------------------------------------------------------;; Setup zp;	jsr QDStart;------------------------------------------------------;; Read the source loc info from user to	zp.;	lda PPLocInfo,s	sta Temp2	lda PPLocInfo+2,s	sta Temp2+2	ldy #LocSize-2	; move srclocinfo to zpLoop1	tyx	lda [Temp2],y	sta SrcSCB,x	dey	dey	bpl Loop1;------------------------------------------------------;; The dest loc info	is from the current	graf port.	jsl PortLoc2ZP	; move dest info to	zp;------------------------------------------------------;; Read source rect from memory to zp.;	lda PPSrcRect,s	sta temp2	lda PPSrcRect+2,s	sta temp2+2	ldy #6Loop3	tyx	lda [Temp2],y	sta SrcRect,x	dey	dey	bpl Loop3;------------------------------------------------------;; Get dest point off stack onto zp.;	lda PPDestY,s	sta DestPoint	lda PPDestX,s	sta DestPoint+2;----------------------------------------------------;; Extend the destpoint into a rectangle	of the same; size.;	lda SrcRect+4	sec	sbc SrcRect	clc	adc DestPoint	sta DestPoint+4	lda SrcRect+6	sec	sbc SrcRect+2	clc	adc DestPoint+2	sta DestPoint+6;------------------------------------------------------;; Get transfer mode	from stack to zero page.;	lda PPMode,s	sta XFerMode;------------------------------------------------------;; Bring clip and vis rgn to zero page.;	jsl SetUpPortRegions	lda #WideOpen	; put fake region in here	sta RgnHandleC	lda #^WideOpen	sta RgnHandleC+2;----------------------------------------------------------;; Set flag to indicate that we need to clip to port rect;	lda #$8000	sta ClipToPortToo;------------------------------------------------------;; Call standard pixels.;	jsl CallPP	; error comes back in a	pha	; save the error	DirtyPort	; reset the port dirty flags	pla	; and restore the port;------------------------------------------------------;; Error returned in	a reg.;	tax	ldy #14	jmp BusyErr	ENDP;                copy pixel.maps/scroll.rect****************************************************************** ScrollRect    (TheRect : rect; *                dh, dv : integer; *                UpdateRgn : handle);***** The Flow of control**     1.  I bring the portlocinfo to zero page as the SrcLocInfo*         and the DestLocInfo.  This includes the PortRect as the*         SrcRect and the DestRect.   **     2.  Next I get the target rect and clip it myself to the*         the portrect and store it in SrcRect and DestRect.  I*         clip it myself here because I	have to store it in *         the same place as the PortRect.**     3.  Next I get dV and dH off the stack and turn the TargetRect*         stored at	SrcRect and DestRect into the Src and Dest rects*         needed by	StdPixels.**     4.  Next, I set XferMode to indicate Copy.**     5.  Finally, I use the clipRgn and visRgn to create the src*         and dest region for use with stdpixels.**     6.  After calling StdPixels, I create a region that is the difference*         of the src and dest regions and erase it.** Warning to all who follow:*     *     StdPixels takes advantage of the fact that the DestLocInfo*     lives on the same part of zeropage as the PortLocInfo	does*     for routines that use the grafport.  Doing this allows me to*     use GetMinRect to clip the target	rect to the intersection*     of the BoundsRect, PortRect, VisBounds and ClipBounds.******************************************************************	EXPORT ScrollRectScrollRect	PROC*              using CoreData*              using E0VectorsOrigDirect	equ 1	1RTL1	equ OrigDirect+2	3RTL2	equ RTL1+3	7UpdateRgn	equ RTL2+3	AdV	equ UpdateRgn+4	CdH	equ dV+2	ETheRectPtr	equ dH+2	11;-----------------------------------------------;; First we get the inputs from memory to zero; page;	jsr QDStart		DirtyPort	; reset all the dirty DPFlags 	ldy #LocSize+8-2	; move grafport loc	info to src andLoop1	tyx	; dest locinfo on zp	lda [PortRef],y	sta SrcSCB,x	sta DestSCB,x	dey	dey	bpl Loop1;----------------------------------------------; ; Now I get the target rect and put it into; SrcRect and DestRect after clipping it to; the portrect (which is currently stored at; SrcRect and DestRect)	phb	; save bank	lda TheRectPtr+1,s	; put low word in x	tax	lda TheRectPtr+2,s	; set bank to bank with target	phb	; rect	sta 0,s	plb	lda |0,x	cmp SrcRect	bmi ClipTop	sta SrcRect	sta DestRectClipTop	lda |2,x	cmp SrcRect+2	bmi ClipLeft	sta SrcRect+2	sta DestRect+2ClipLeft	lda |4,x	cmp SrcRect+4	bpl ClipBot	sta SrcRect+4	sta DestRect+4ClipBot	lda |6,x	cmp SrcRect+6	bpl ClipRight	sta SrcRect+6	sta DestRect+6ClipRight		; 	plb	; restore bank register;----------------------------------------------;; Now I adjust the SrcRect and DestRect; accordingly for dH and dV.	lda dV,s	; get dV	bmi MoveUp	clc	; dv is positive so	the top of the	adc DestRect	; dest rect is lower by dV than the	sta DestRect	; top of the TargetRect	lda SrcRect+4	; dV is positive so	the bottom	sec	; of SrcRect is dV from the bottom	sbc dV,s	; of the target rect	sta SrcRect+4	bra AdjustHorMoveUp	clc	; dV is negative so	the top of the	adc DestRect+4	; dest rect is the TargetRect, but	sta DestRect+4	; the bottom is less than the bottom*		; of the targetrect.*		; Note that I add Neg to Pos to get*		; this to work	lda SrcRect	; dV is negative so	the bottom of	sec	; SrcRect is the bottom of the Target	sbc dV,s	; Rect, but the top	of the SrcRect is	sta SrcRect	; below the top of TargetRect* Now I do the same	shit for the horizontalAdjustHor	lda dH,s	; get dV	bmi MoveLeft	clc	; dH is positive so	the left of the	adc DestRect+2	; dest rect is to rt by dH more than	sta DestRect+2	; left of the TargetRect	lda SrcRect+6	; dH is positive so	the right	sec	; of SrcRect is dH from the right	sbc dH,s	; of the target rect	sta SrcRect+6	bra AllAdjustedMoveLeft	clc	; dH is negative so	the left of the	adc DestRect+6	; dest rect is the TargetRect, but	sta DestRect+6	; the right is less	than the right*		; of the targetrect.*		; Note that I add Neg to Pos to get*		; this to work	lda SrcRect+2	; dH is negative so	the right of	sec	; SrcRect is the right of the Target	sbc dH,s	; Rect, but the left of the SrcRect is	sta SrcRect+2	; to rt the left of	TargetRectAllAdjusted		; ;----------------------------------------------;; Set the xfermode and the regions and we're; ready to call StdPixels.	stz XFerMode	; set the transfer mode;-------------------------------------------------;; We create the;     srcRgn := DestRect SECT VisRgn SECT ClipRgn;; But before we do this we must save the srcrect and; destrect since the Rgn calls we are about to make; will destroy this	part of zero page.;	tdc	tax	ldy #ZZEndOfSlice-CombinedMask ; num bytes to saveSaveLoop	lda >CombinedMask,x	sta >0+512,x	inx	inx	dey	dey	bpl SaveLoop;----------------------------------------------------;; Now I hope it is safe;;	PushLong PortRef	; get this on the stack for now	PushLong #0	; get two new region	_NewRgn	bcc Got1Rgn	plx	plx	jmp Error0Got1Rgn	PushLong #0	_NewRgn	bcc Got2Rgn	plx	; get unused space for handle off	plx	; stack	plx	; get handle of rgn	1 off stack into	ply	; x and y	pha	; put error code on	stack	phy	; put handle of rgn	1 back on stack	phx	_DisposeRgn	; dispose of it	pla	; get error back	jmp Error0	; quitGot2Rgn	phd	; save direct register	tsc	tcdxDirect	equ 1	; these are equates	for thisxSrcRgn	equ 3	; temporary zpxDestRgn	equ 7xPortRef	equ 11StackAddition	equ 14	; 14 new bytes on stack	pei xSrcRgn+2	; SetRectRgn(SrcRgn,left,top,right,bot)	pei xSrcRgn	pei TheRectPtr+StackAddition+2	pei TheRectPtr+StackAddition	_RectRgn	bcc cont1	jmp ErrorDcont1	pei xSrcRgn+2	; SrcRgn := SrcRgn SECT VisRgn	pei xSrcRgn	ldy #o_VisRgn+2	lda [xPortRef],y	pha	dey	dey	lda [xPortRef],y	pha	pei xSrcRgn+2	pei xSrcRgn	_SectRgn	bcc cont2	jmp ErrorDcont2	pei xSrcRgn+2	; SrcRgn := ClipRgn	SECT SrcRgn	pei xSrcRgn	ldy #o_ClipRgn+2	lda [xPortRef],y	pha	dey	dey	lda [xPortRef],y	pha	pei xSrcRgn+2	pei xSrcRgn	_SectRgn	bcc cont3	jmp ErrorD;-------------------------------------------------;; DestRgn = Offset SrcRgn;cont3	pei xSrcRgn+2	; DestRgn := SrcRgn	pei xSrcRgn	pei xDestRgn+2	pei xDestRgn	_CopyRgn	bcc cont4	jmp ErrorDcont4	pei xDestRgn+2	pei xDestRgn	pei dh+StackAddition	pei dv+StackAddition	_OffsetRgn	bcc cont5	jmp ErrorD;----------------------------------------------------;; Now I restore my zp and put the src and dest rgn; in RgnHandleA and	RgnHandleB;cont5	pld	; restore direct	pla	sta RgnHandleA	; this is srcrgn	pla	sta RgnHandleA+2	pla	sta RgnHandleB	pla	sta RgnHandleB+2	pla	; pull off port ref	pla	lda #WideOpen	sta RgnHandleC	lda #^WideOpen	sta RgnHandleC+2;---------------------------------------------------------;; Now I restore SrcRect and DestRect;	tdc	tax	ldy #ZZEndOfSlice-CombinedMask ; num bytes to restoreRepLoop	lda >0+512,x	sta >CombinedMask,x	inx	inx	dey	dey	bpl RepLoop;----------------------------------------------------------;; Set flag to indicate that we do not clip to port rect;	stz ClipToPortToo	jsl RgnBlt	; comes back with error in a	bcs Error0;----------------------------------------------;; Finally I must create the update region and; erase it.;; Update Region = SrcRgn - DestRgn;	pei RgnHandleB+2	; save these on the	stack	pei RgnHandleB	; so can call diff rgn	pei RgnHandleA+2	pei RgnHandleAyDirect	equ 1yHandleA	equ 3yHandleB	equ 7yStackSize	equ 10	phd	tsc	tcd	pei yHandleA+2	pei yHandleA	pei yHandleB+2	pei yHandleB	pei yHandleA+2	pei yHandleA	_DiffRgn	bcs ErrorD	pei yHandleA+2	pei yHandleA	_EraseRgn;-------------------------------------------------;; If the update region passed to this routine is; a nil handle then	we just free the regions I've; created.  If it is not nil, then I copy the update; region into it.	lda UpdateRgn+yStackSize	ora UpdateRgn+yStackSize+2	beq ReturnNothing	pei yHandleA+2	pei yHandleA	pei UpdateRgn+yStackSize+2	pei UpdateRgn+yStackSize	_CopyRgn	bcs ErrorD;-------------------------------------------------;; Free the regions (and any other political; prisoners you can	find).ReturnNothing	pld	_DisposeRgn	_DisposeRgn	ldy #12	jmp BusyECErrorD	pha	pei yHandleA+2	pei yHandleA	_DisposeRgn	pei yHandleB+2	pei yHandleB	_DisposeRgn	pla	pldError0	tax	ldy #12	jmp BusyErr	ENDP;                copy pixel.maps/paint.pixels****************************************************************** PaintPixels   (PPRecPtr : Ptr);** The PPRec is as follows:**     PtrToSourceLocInfo*     PtrToDestLocInfo*     PtrToSourceRect*     PtrToDestPoint*     Mode*     HandleToClipRegion*** The LocInfo Record Looks Like**     MasterSCB	    byte*     Reserved	    byte*     PtrToPixelMap	    long*     Width	    word*     BoundsRect	    rect*** The Flow of control**     1.  Bring everything to zero page*     2.  Check to see if the transfer makes sense (SCB's*         must match).*     3.  Set up for the slice routines*     4.  Loop calling the slice routines until all*         lines are	transferred.*****************************************************************	EXPORT PaintPixelsPaintPixels	PROC*              using CoreDataOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3PPRecPtr	equ RTL2+3;-----------------------------------------------;; First we get the inputs from memory to zero; page;	jsr QDStart	DirtyPort	; reset dirtyDPFlags here		lda PPRecPtr,s	sta Temp	tax	lda PPRecPtr+1,s	phb	pha	plb	plb	lda |0,x	; get pointer to SrcLocInfo	sta Temp2	lda |1,x	sta Temp2+1	ldy #LocSize-2	; move srclocinfo to zpLoop1	tyx	lda [Temp2],y	sta SrcSCB,x	dey	dey	bpl Loop1	ldx Temp	; get back pointer to paramlist	lda |4,x	; get pointer to DestLocInfo	sta Temp2	lda |5,x	sta Temp2+1	ldy #LocSize-2	; move srclocinfo to zpLoop2	tyx	lda [Temp2],y	sta DestSCB,x	dey	dey	bpl Loop2	ldx Temp	; get back pointer to paramlist	lda |8,x	; get pointer to Source Rect	sta Temp2	lda |9,x	sta Temp2+1	ldy #6	; move SourceRect to zpLoop3	tyx	lda [Temp2],y	sta SrcRect,x	dey	dey	bpl Loop3	ldx Temp	; get back pointer to paramlist	lda |12,x	; get pointer to DestLocInfo	sta Temp2	lda |13,x	sta Temp2+1	lda [Temp2]	; get the dest point	sta DestPoint	ldy #2	lda [Temp2],y	sta DestPoint+2	lda SrcRect+4	; stretch the dest point into	sec	; a rect that is the same	sbc SrcRect	; size as the SrcRect.	clc	adc DestPoint	sta DestPoint+4	lda SrcRect+6	sec	sbc SrcRect+2	clc	adc DestPoint+2	sta DestPoint+6	lda |16,x	; get xfer mode	sta XFerMode	lda #WideOpen	; put wide open in all the	sta RgnHandleA	; region handles.	sta RgnHandleB	sta RgnHandleC	lda #^WideOpen	sta RgnHandleA+2	sta RgnHandleB+2	sta RgnHandleC+2	lda |18,x	; now look at the handle	ora |20,x	; passed by user	beq UseFake	; if it is nil, we are set	lda |18,x	; else copy theirs to C	sta RgnhandleC	lda |20,x	sta RgnHandleC+2UseFake	plb	; restore the bank register;----------------------------------------------------------;; Set flag to indicate that we do not clip to port rect;	stz ClipToPortToo	jsl CallPP	; error comes back in a	tax	ldy #4	jmp BusyErr	; (if any)	ENDP;                copy pixel.maps/slice.setup****************************************************************** SliceSetup** This routine sets	up the following zp	variables:**      NumSrcWords	           NumDestWords	 *      SrcStartWord	           DestStartWord*      SrcFinishWord           DestFinishWord*	           LeftMask*	           RightMask** NumSrcWords and NumDestWords are mis-named because they really* tell me the number of bytes, not words.*** It also adjust the boundries for the case where the* number of words in the source and destination are different.** Consider the three possiblities** Source	         Dest** xxxx|abcd|efgh|ijkl|xxxx   xxxx|abcd|efgx|xxxx     S = D* xxxx|abcd|efgh|ijkl|xxxx   xxxa|bcde|fxxx|xxxx     S < D* xxxx|abcd|efgh|ijkl|xxxx   xxxx|xdex|xxxx|xxxx     S > D** When the source =	destination then nothing tricky happens.* When Source < Destination then we pretend to transfer*      one extra word from the source so that the last shift*      out from the	source can get to the destination.* When Source > Destination then we start the destinaton*      one word sooner so that the first shift out from the*      source can get to the destination.*****************************************************************	EXPORT iSliceSetUpiSliceSetUp	PROC;-------------------------------------------------;; Now we decide which mode were working	in so; that we set up the mode dependent stuff;	bit SrcSCB-1	bmi Is640;-------------------------------------------------;; The mode is 320.;	lda SrcRect+2	; get left edge of source	sec	; change to global coords	sbc SrcBounds+2	sta HowFarToShift	; save copy here for later	lsr a	; half it so it refers to byte	and #$FFFE	; mask so refers to	even byte	sta SrcStartWord	lda SrcRect+6	; get right edge of	source	dec a	; one less so don't write too much	sec	; chage to global coords	sbc SrcBounds+2	;	lsr a	; half it so it refers to byte	and #$FFFE	; mask so refers to	even byte	sta SrcFinishWord	lda DestRect+2	; get dest x	sec	sbc DestBounds+2	tax	; save copy here for later	lsr a	; half for byte	and #$FFFE	; mask for even byte	sta DestStartWord	lda DestRect+6	dec a	sec	sbc DestBounds+2	lsr a	; half for byte	and #$FFFE	; mask for even byte	sta DestFinishWord;-------------------------------------------------;; Now I discover which pixel in the word source; and dest are.;	lda HowFarToShift	; this was global first src pixel saved	and #3	; above	sta HowFarToShift	txa	; this was global first dest pixel saved	and #3	; above	cmp HowFarToShift	bcs AllIsWell320;-------------------------------------------------;; The DestPixel is < SrcPixel.  So we have to; decrement the DestStartWord by 2;	dec DestStartWord	dec DestStartWord	clc	adc #4AllIsWell320		; 	sec	sbc HowFarToShift	asl a	; make into 0, 4, 8	or 12	asl a	bra RazzleDazzle;-------------------------------------------------;;  The Mode is 640;Is640	lda SrcRect+2	; get left edge of source	sec	; convert to global	coords	sbc SrcBounds+2	sta HowFarToShift	lsr a	; div by 4	lsr a	; so it refers to byte	and #$FFFE	; mask so it is even byte	sta SrcStartWord	lda SrcRect+6	; get right edge of	source	dec a	; one less so don't write too much	sec	sbc SrcBounds+2	lsr a	; div by 4 so it	lsr a	; refers to byte	and #$FFFE	; mask so it is even byte	sta SrcFinishWord	lda DestRect+2	; convert dest to global	sec	sbc DestBounds+2	tax	lsr a	; div by 4 for	lsr a	; byte	and #$FFFE	; mask so it is even byte	sta DestStartWord	lda DestRect+6	dec a	sec	sbc DestBounds+2	lsr a	; make into number of byte	lsr a	and #$FFFE	; make it an even byte	sta DestFinishWord	; store;-------------------------------------------------;; Now I discover which pixel in the word source; and dest are.;	lda HowFarToShift	; this was global first src pixel saved	and #7	; above	sta HowFarToShift	txa	; this was global first dest pixel saved	and #7	; above	cmp HowFarToShift	bcs AllIsWell640;-------------------------------------------------;; The DestPixel is < SrcPixel.  So we have to; decrement the DestStartWord by 2;	dec DestStartWord	dec DestStartWord	clc	adc #8AllIsWell640		; 	sec	sbc HowFarToShift	asl a	; make 0, 2, 4, 6, 8 ...RazzleDazzle		; 	asl a	; double it	sta HowFarToShift	lda DestFinishWord	sec	sbc DestStartWord	sta NumDestWords	lda SrcFinishWord	sec	sbc SrcStartWord	sta NumSrcWords	cmp NumDestWords	beq AllDone	bcc SrcIsLess;-------------------------------------------------;; NumSrcWords > NumDestWords.  So make left mask; zero and decrement the dest start Word by two	lda #0	; left mask must be	zero	sta LeftMask	dec DestStartWord	dec DestStartWord	inc NumDestWords	inc NumDestWords	rtl;-------------------------------------------------;; NumSrcBytes < NumDestBytes.  So Increment; the SrcFinishWord	by two.SrcIsLess	inc SrcFinishWord	inc SrcFinishWord	inc NumSrcWords	inc NumSrcWordsAllDone	rtl	ENDP****************************************************************** CallPP** Local Routine to call the StdPixel routine (or user routine)*****************************************************************	EXPORT CallPPCallPP	PROC*              using QDProcs*              using E0Vectors;-------------------------------------------------;; If the destination loc info is the same as; the loc info in the current graf port, I must use; the bottle neck proc in the grafport.	jsr IsDestPort	bcc UseStandard	jsr TestGPs	bcs NotStandardUseStandard	jml StdPixelsNotStandard	phb	; put extra byte on	stack	ldy #o_stdpixels	lda [Temp],y	; get low word	pha	; put on stack	iny	; get middle and	lda [Temp],y	; high byte	sta 2,s	; overstore middle byte on stack	rtl	; go there	ENDP****************************************************************** IsDestPort** Compares the destination loc info with the loc info* of the graf port.	 if they are the same, then the carry is* set.  Different, carry is clear.*****************************************************************	EXPORT IsDestPortIsDestPort	PROC*              using CoreDATA	ldy #LocSize-2Loop	tyx	lda [PortRef],y	cmp DestSCB,x	bne No	dey	dey	bpl Loop	sec	rtsNo	clc	rts	ENDP	EXPORT iSetSliceAdriSetSliceAdr	PROC*              using E0Vectors	lda XFerMode	; take the tranfer mode	and #$7F	; mask off not bit	asl a	; double	asl a	; and double again	tax	; put in x	lda HowFarToShift	; if i don't have to shift at all	beq UseFastSlices	; then I can use the fast slice routines	bit HorBackward	; oh well so I use the slow ones.	bpl SlowHorIsForward	lda >BackSliceAdrTable,x	sta >ToSlice	lda >BackSliceAdrTable+2,x	bra StoreItSlowHorIsForward		; 	lda >SliceAdrTable,x	sta >ToSlice	lda >SliceAdrTable+2,xStoreIt	sta >ToSlice+2	rtlUseFastSlices		; ;-------------------------------------------------;; I know that I can	use the fast routines, can I; use the really fast copy routine?;	lda XferMode	; transfer mode must be 0!	bne NotSpecial	lda NonRectRegions	; are the clipping regions rectangular?	bne NotSpecial	lda NumDestWords	; are we copying at	least 6 bytes?	cmp #4	bcc NotSpecial	lda SrcPixelMapRef+1 ; are source and dest equal to screen?	cmp DestPixelMapRef+1	bne NotSpecial	and #$0FFF	; strip off the high nibble	cmp #$0120	; on either screen???	bne NotSpecial		sec	; yes Special	bra GoOnNotSpecial	clcGoON		; 	bit HorBackward	; forward or back	bpl FastHorIsForward	bcc NotSoFastBack	lda >RealFastBack	sta >ToSlice	lda >RealFastBack+2	bra StoreItNotSoFastBack		; 	lda >FastBackSliceAdrTable,x	sta >ToSlice	lda >FastBackSliceAdrTable+2,x	bra StoreItFastHorIsForward		; 	bcc NotSoFastForward	lda >RealFastForward	sta >ToSlice	lda >RealFastForward+2	bra StoreItNotSoFastForward		; 	lda >FastSliceAdrTable,x	sta >ToSlice	lda >FastSliceAdrTable+2,x	bra StoreIt	ENDP	EXPORT SliceAdrTableSliceAdrTable	PROC	jml FCopySlice	jml FORSlice	jml FXORSlice	jml FBICSlice	ENDP	EXPORT BackSliceAdrTableBackSliceAdrTable	PROC	jml BFCopySlice	jml BFORSlice	jml BFXORSlice	jml BFBICSlice	ENDP	EXPORT FastSliceAdrTableFastSliceAdrTable	PROC	jml fFCopySlice	jml fFORSlice	jml fFXORSlice	jml fFBICSlice	ENDP	EXPORT FastBackSliceAdrTableFastBackSliceAdrTable PROC	jml fBFCopySlice	jml fBFORSlice	jml fBFXORSlice	jml fBFBICSlice	ENDP	EXPORT RealFastBackRealFastBack	PROC	jml bRealFastCopy	ENDP	EXPORT RealFastForwardRealFastForward	PROC	jml fRealFastCopy	ENDP	END